"use client";

import { cn } from "@/lib/cn";
import { duration, ease, hold, useMotionSuppressed, withSuppression } from "@/lib/motion";
import { AnimatePresence, motion } from "motion/react";
import { forwardRef, useEffect, useMemo, useRef } from "react";

import type { SwapProps } from "./types";

/** Seconds, because motion/react speaks seconds. */
export const SWAP_TIMELINE = {
    enter: duration.fast,
    hold: hold.tight,
    exit: (duration.fast * 2) / 3, // Exits run at two-thirds of their entrance
} as const;

export const SWAP_ENTER_DELAY = SWAP_TIMELINE.exit + SWAP_TIMELINE.hold;
const TOTAL = SWAP_ENTER_DELAY + SWAP_TIMELINE.enter;

if (process.env.NODE_ENV !== "production" && TOTAL > 0.3) {
    console.warn(`Swap exceeds 300ms micro-interaction ceiling (${TOTAL * 1000}ms)`);
}

const OFFSET = 8; // Vertical travel for numeric swaps

export const Swap = forwardRef<HTMLSpanElement, SwapProps>(function Swap(
    { value, children, inline = true, className, ...props },
    ref
) {
    const suppressed = useMotionSuppressed();
    const numeric = typeof value === "number";

    const previous = useRef<string | number>(value);
    const direction = useMemo(() => {
        if (!numeric || typeof previous.current !== "number") {
            return 0;
        }
        return Math.sign((value as number) - previous.current);
    }, [value, numeric]);

    useEffect(() => {
        previous.current = value;
    }, [value]);

    const enterTransition = withSuppression(
        { duration: SWAP_TIMELINE.enter, delay: SWAP_ENTER_DELAY, ease: ease.inOut },
        suppressed
    );
    const exitTransition = withSuppression(
        { duration: SWAP_TIMELINE.exit, ease: ease.inOut },
        suppressed
    );

    return (
        <span
            ref={ref}
            className={cn(
                "relative inline-grid place-items-center overflow-visible",
                "[grid-template-areas:'swap']",
                "*:[grid-area:swap]",
                !inline && "grid",
                numeric && "tabular-nums",
                className
            )}
            {...props}
        >
            <AnimatePresence mode="popLayout" initial={false}>
                <motion.span
                    key={String(value)}
                    initial={{
                        opacity: 0,
                        scale: 1.04,
                        y: direction * OFFSET,
                    }}
                    animate={{
                        opacity: 1,
                        scale: 1,
                        y: 0,
                        transition: enterTransition,
                    }}
                    exit={{
                        opacity: 0,
                        scale: 0.94,
                        y: direction * -OFFSET,
                        transition: exitTransition,
                    }}
                >
                    {children}
                </motion.span>
            </AnimatePresence>
        </span>
    );
});

import type * as React from "react";

export type SwapProps = Omit<React.HTMLAttributes<HTMLSpanElement>, "children"> & {
    /**
     * The identity of the current content. When it changes, the swap plays.
     *
     * Numeric values additionally derive direction: a value that increased
     * enters from below, one that decreased enters from above. That inference
     * is semantic, not configuration - there is no direction prop.
     */
    value: string | number;
    /** The content for the current value. */
    children: React.ReactNode;
    /**
     * Lay out as an inline element (default) or a block.
     * Inline suits icons and digits inside text; block suits standalone slots.
     *
     * \@default true
     */
    inline?: boolean;
};

export { Swap } from "./Swap";
export type { SwapProps } from "./types";
export { SWAP_TIMELINE, SWAP_ENTER_DELAY } from "./Swap";
